export async function execMetadata(hostArgs: Record<string, unknown>) {
  {
    const info = hostArgs as Record<string, any>;
    info.user_agent = legacyCompat.userAgent();
    for (const c of (info.user_agent_cookies ?? []) as { name: string; value: string; domain: string; path: string }[]) {
      info.user_agent.cookie_jar.add(c);
    }
  }
  interface ExecMetadataInfo extends Required<Pick<MetadataHostArgs, "file_path">> {
    user_agent: LegacyUserAgent;
    user_agent_cookies?: LegacyCookie[];
  }
  // (shift) discarded positional arg — legacy Perl-OOP invocant/first @_ slot
  let lrr_info = hostArgs as unknown as ExecMetadataInfo;
  let logger = legacyCompat.getLogger("koromo", "plugins");
  let file = lrr_info["file_path"];
  let path_in_archive = (hostArgs.sidecar_files as Record<string, string> | undefined)?.["Info.json"];
  if (!(path_in_archive)) {
    path_in_archive = (hostArgs.sidecar_files as Record<string, string> | undefined)?.["info.json"];
  }
  if (! path_in_archive) {
    throw new PluginErrorException("No koromo info.json file found in this archive!");
  }
  let filepath = path_in_archive;
  let stringjson = "";
  let fh = filepath;
  if (fh === undefined) { throw new PluginErrorException("Could not open file", { filepath }); }
  for (let row of (fh ?? "").split(/\r?\n/)) {
    row = legacyCompat.chomp(row);
    stringjson += row;
  }
  let hashjson = JSON.parse(stringjson);
  logger.debug(`Found and loaded the following JSON: ${stringjson}`);
  let [tags, title] = tags_from_koromo_json(hashjson);
  ;
  logger.info(`Sending the following tags to LRR: ${tags}`);
  if (title) {
    logger.info(`Parsed title is ${title}`);
    return { tags: tags, title: title };
  } else {
    return { tags: tags };
  }
}

function tags_from_koromo_json(...args: any[]) {
  let hash = args[0];
  let found_tags = [] as any[];
  let title = hash["Title"];
  let tags = hash["Tags"];
  let characters = hash["Characters"];
  let series = hash["Series"];
  let magazine = hash["Magazine"];
  let parody = hash["Parody"];
  let groups = hash["Groups"];
  let artist = hash["Artist"];
  let artists = hash["Artists"];
  let language = hash["Language"];
  let type = hash["Types"];
  let url = hash["URL"];
  handle_tag_yaml("", tags, found_tags);
  handle_tag_yaml("character:", characters, found_tags);
  handle_tag_yaml("series:", series, found_tags);
  handle_tag_yaml("group:", groups);
  handle_tag_yaml("artist:", artists, found_tags);
  handle_tag_yaml("series:", parody, found_tags);
  handle_tag_yaml("artist:", artist, found_tags);
  handle_tag_yaml("magazine:", magazine, found_tags);
  handle_tag_yaml("language:", language, found_tags);
  handle_tag_yaml("category:", type, found_tags);
  handle_tag_yaml("source:", url, found_tags);
  let concat_tags = found_tags.join(", ");
  return [concat_tags, title];
}

function handle_tag_yaml(...args: any[]) {
  let namespace = args[0];
  let yamldata = args[1];
  if (Array.isArray(yamldata)) {
    for (let tag of yamldata) {
      args[2].push(`${namespace}${tag}`);
    }
  } else if ((yamldata !== undefined && yamldata !== null)) {
    args[2].push(`${namespace}${yamldata}`);
  }
}
